  margin: 1rem auto;
  padding: 1rem;
  background: #fff;
  border-radius: 5px;
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
}

form input[type="text"], form input[type="email"], form input[type="password"], form textarea {
  width: 100%;
  padding: 0.5rem;
  margin: 0.5rem 0;
  border: 1px solid #ccc;
  border-radius: 5px;
}

form button {
  width: 100%;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  margin: 1rem 0;
}

table th, table td {
  border: 1px solid #ddd;
  padding: 0.75rem;
  text-align: left;
}

table th {
  background: #5a67d8;
  color: #fff;
}

table tr:nth-child(even) {
  background: #f4f4f9;
}

table tr:hover {
  background: #ddd;
}

/* Leaderboard */
.leaderboard {
  margin: 2rem auto;
  max-width: 800px;
  border: 1px solid #ddd;
  border-radius: 5px;
  overflow: hidden;
}

.leaderboard-header {
  background: #5a67d8;
  color: #fff;
  padding: 1rem;
  text-align: center;
}

.leaderboard-item {
  display: flex;
  justify-content: space-between;
  padding: 1rem;
  border-bottom: 1px solid #ddd;
}

.leaderboard-item:last-child {
  border-bottom: none;
}

.leaderboard-item .rank {
  font-weight: bold;
  color: #5a67d8;
}

